//! Regenerate original compact KPK knowledge with the authoritative native rules.
//!
//! cargo run --release --locked -p mshogi-search --example generate_chess_kpk -- OUTPUT
//! Add --check to compare OUTPUT with generated bytes instead of replacing it.
//! No upstream code or table data is used. This development-only retrograde
//! solver has no runtime role in the shipped engine.
#[path = "../src/chess_kpk.rs"]
mod chess_kpk;

use mshogi_core::chess::{Color, PieceKind, Position, Promotion, Square};
use std::{env, fs, time::Instant};

#[derive(Default)]
struct Node {
    children: Vec<usize>,
    strong_turn: bool,
    escape: bool,
    win: bool,
    valid: bool,
}

fn diagram(index: usize) -> Option<Position> {
    let turn = index % 2;
    let weak = index / 2 % 64;
    let strong = index / 128 % 64;
    let slot = index / 8192;
    let pawn = (slot / 4 + 1) * 8 + slot % 4;
    if weak == strong || weak == pawn || strong == pawn {
        return None;
    }
    let mut board = [' '; 64];
    board[weak] = 'k';
    board[strong] = 'K';
    board[pawn] = 'P';
    let mut fen = String::with_capacity(40);
    for rank in (0..8).rev() {
        if rank != 7 {
            fen.push('/');
        }
        let mut empty = 0;
        for file in 0..8 {
            let piece = board[rank * 8 + file];
            if piece == ' ' {
                empty += 1;
            } else {
                if empty != 0 {
                    fen.push(char::from(b'0' + empty));
                    empty = 0;
                }
                fen.push(piece);
            }
        }
        if empty != 0 {
            fen.push(char::from(b'0' + empty));
        }
    }
    fen.push_str(if turn == 0 {
        " w - - 0 1"
    } else {
        " b - - 0 1"
    });
    Position::from_fen(&fen).ok()
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<_> = env::args().skip(1).collect();
    let destination = args.first().ok_or("expected output path [--check]")?;
    let check = args.get(1).is_some_and(|arg| arg == "--check");
    if args.len() > 2 || (args.len() == 2 && !check) {
        return Err("expected output path [--check]".into());
    }
    let started = Instant::now();
    let mut nodes: Vec<_> = (0..chess_kpk::STATES).map(|_| Node::default()).collect();
    let mut valid = 0;
    let mut edges = 0;
    let mut seeds = 0;
    for (i, node) in nodes.iter_mut().enumerate() {
        let Some(position) = diagram(i) else { continue };
        assert_eq!(chess_kpk::index(&position), Some((i, Color::White)));
        node.valid = true;
        valid += 1;
        node.strong_turn = position.side_to_move() == Color::White;
        let actions = position.legal_actions();
        if actions.is_empty() {
            node.win = !node.strong_turn && position.in_check();
            node.escape = !node.win;
        }
        for action in actions {
            let mut child = position.clone();
            child.apply(action)?;
            if let Some(promotion) = action.promotion {
                // In KQK/KRK a safe major piece wins unless promotion causes
                // stalemate. Immediate capture and all minor promotions draw.
                // No hand-written legal geometry: native replies decide both.
                let replies = child.legal_actions();
                let mate = replies.is_empty() && child.in_check();
                let safe_major = matches!(promotion, Promotion::Queen | Promotion::Rook)
                    && !replies.is_empty()
                    && !replies.iter().any(|reply| reply.to == action.to);
                node.win |= mate || safe_major;
                continue;
            }
            if let Some((child_index, _)) = chess_kpk::index(&child) {
                node.children.push(child_index);
                edges += 1;
            } else {
                // Only a defending king capturing the sole pawn can leave KPK.
                assert!(!node.strong_turn);
                assert!((0..64).all(|s| {
                    child
                        .piece_at(Square::new(s % 8, s / 8).unwrap())
                        .is_none_or(|piece| piece.kind == PieceKind::King)
                }));
                node.escape = true;
            }
        }
        if node.win {
            seeds += 1;
        }
    }
    // Monotone least fixed point of reachability to a native safe-promotion or
    // mate seed. Unresolved cycles allow the defender to avoid conversion and
    // are draws. A defending escape prevents a universal-win conclusion.
    let mut passes = 0;
    loop {
        let mut added = 0;
        for i in 0..nodes.len() {
            let node = &nodes[i];
            if !node.valid || node.win {
                continue;
            }
            let win = if node.strong_turn {
                node.children.iter().any(|&child| nodes[child].win)
            } else {
                !node.escape
                    && !node.children.is_empty()
                    && node.children.iter().all(|&child| nodes[child].win)
            };
            if win {
                nodes[i].win = true;
                added += 1;
            }
        }
        passes += 1;
        if added == 0 {
            break;
        }
        assert!(passes <= chess_kpk::STATES, "finite monotone convergence");
    }
    let mut bytes = vec![0u8; chess_kpk::STATES / 8];
    let mut wins = 0;
    for (i, node) in nodes.iter().enumerate() {
        if node.win {
            bytes[i / 8] |= 1 << (i % 8);
            wins += 1;
        }
    }
    if check {
        assert_eq!(fs::read(destination)?, bytes, "generated data changed");
        // Exercise the same included product lookup against every valid state.
        for (i, node) in nodes.iter().enumerate().filter(|(_, node)| node.valid) {
            assert_eq!(chess_kpk::probe(&diagram(i).unwrap()), Some(node.win));
        }
    } else {
        fs::write(destination, &bytes)?;
    }
    println!(
        "states={} valid={valid} edges={edges} seeds={seeds} wins={wins} passes={passes} bytes={} elapsed={:?} check={check}",
        chess_kpk::STATES,
        bytes.len(),
        started.elapsed()
    );
    Ok(())
}
